    const bB = r.bottom / Z, bT = r.top / Z, bL = r.left / Z, bR = r.right / Z;
    // vertical: open below, flip above if overflow — use cssBottom so actual height doesn't matter
    const flipAbove = bB + 4 + estH > vpH - 8;
