              <div style={{ position: "absolute", left: 10, top: 0, borderRadius: 1, overflow: "hidden", boxShadow: "0 1px 3px rgba(0,0,0,0.6)", zIndex: 1 }}><FlagSvg code={currentSymbol.quote} w={22} h={14}/></div>
